raw_first:
{
 "rules": [
  {
   "rule_id": "P005-S2-R11-01",
   "status": "OK",
   "label": "이자 계산 기간",
   "source": {
    "quote": "▪ 예금일부터 지급일 전날까지(결산 시에는 지난 원가일부터 원가일 전날까지)를 이자계산 기간으로 하고, 매일의 최종잔액을 평균하여 결산일 현재 지점 및 KB국민은행 홈페이지에 고시하는 금리로 계산"
   },
   "effect": {
    "type": "STATE_CHANGE",
    "target": "RESERVE_OFF"
   }
  },
  {
   "rule_id": "P005-S2-R11-02",
   "status": "OK",
   "label": "신규 가입 시 특별금리 적용",
   "source": {
    "quote": "▪ 이 통장에 신규 가입한 경우 처음 도래하는 결산일에는 특별금리 적용조건 충족 여부에 관계없이 특별금리 적용"
   },
   "condition": {
    "and": [
     {
      "exists": {
       "event": "PRODUCT_SWITCH",
       "within": {
        "ref": "$window"
       }
      }
     },
     {
      "not": {
       "in": [
        {
         "var": "customer.has_product"
        },
        [
         "true"
        ]
       ]
      }
     }
    ]
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": 0.05,
    "unit": "%"
   }
  },
  {
   "rule_id": "P005-S2-R11-03",
   "status": "OK",
   "label": "상품 전환 시 전환 전 금리 적용",
   "source": {
    "quote": "▪ 다른 상품에서 이 통장으로 전환한 경우, 전환 후 처음 도래하는 결산기에 대해서는 전환 전(前) 상품의 금리를 적용하고, 다음 결산기부터 이 통장의 금리 적용"
   },
   "condition": {
    "exists": {
     "event": "PRODUCT_SWITCH",
     "within": {
      "ref": "$window"
     }
    }
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": 0.03,
    "unit": "%"
   }
  }
 ]
}

