  {
   "rule_id": "R-P068-S2-R11-01",
   "status": "OK",
   "label": "자동채우기 주기 선택",
   "source": {
    "quote": "▪ 자동채우기 주기는 매월 5일/10일/15일/20일/25일/30일 중 하나를 선택할 수 있습니다."
   },
   "effect": {
    "type": "REQUIRE",
    "value": "AUTO_FILL_DAY"
   }
  },
  {
   "rule_id": "R-P068-S2-R11-02",
   "status": "OK",
   "label": "자동채우기 등록 즉시 반영",
   "source": {
    "quote": "▪ 자동채우기 등록 및 변경 내용은 다음 날부터 반영되어 처리됩니다."
   },
   "condition": {
    "and": [
     {
      "exists": {
       "event": "AUTO_TRANSFER"
      }
     },
     {
      "not": {
       "in": [
        {
         "var": "contract.start_date"
        },
        [
         "contract.registration_date",
         "contract.modification_date"
        ]
       ]
      }
     }
    ]
   },
   "effect": {
    "type": "STATE_CHANGE",
    "target": "RESERVE_OFF"
   }
  },
  {
   "rule_id": "R-P068-S2-R11-03",
   "status": "OK",
   "label": "통장잔액 부족 시 자동채우기 불가",
   "source": {
    "quote": "▪ 통장잔액이 부족한 경우 자동채우기가 실행되지 않습니다."
   },
   "condition": {
    "not": {
     ">=": [
      {
       "var": "account.balance"
      },
      {
       "var": "contract.amount"
      }
     ]
    }
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  },
  {
   "rule_id": "R-P068-S2-R11-04",
   "status": "UNSUPPORTED",
   "label": "자동채우기와 자동이체의 차이",
   "source": {
    "quote": "▪ 본 서비스의 자동채우기는 은행 내 자동이체약관에 의한 자동이체와는 별도로 제공됩니다."
