raw_first:
{
 "rules": [
  {
   "rule_id": "R-P097-S2-R08-01",
   "status": "OK",
   "label": "자동이체 우대이율",
   "source": {
    "quote": "1 | 자동이체 우대이율 (연0.1%p) | 전회차 저축한 계좌 중 자동이체, 자동화기기, KB스타뱅킹 및 인터넷뱅킹 등을 이용하여 2/3 이상 저축한 만기계좌에 대하여 상기 기본이율과는 별도로 연 0.1%p 추가지급"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.start_date",
       "offset_months": 0,
       "day": "first"
      },
      "to": {
       "anchor": "contract.maturity_date",
       "offset_months": 0,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "and": [
     {
      "exists": {
       "event": "AUTO_TRANSFER",
       "within": {
        "ref": "$window"
       },
       "where": {
        "AUTO_TRANSFER.route": [
         "GIRO",
         "CMS",
         "FIRM_BANKING",
         "CARD"
        ]
       }
      }
     },
     {
      ">=": [
       {
        "count_distinct_months": {
         "event": "AUTO_TRANSFER",
         "within": {
          "ref": "$window"
         },
         "where": {
          "AUTO_TRANSFER.route": [
           "GIRO",
           "CMS",
           "FIRM_BANKING",
           "CARD"
          ]
         }
        }
       },
       2
      ]
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.1,
    "unit": "%"
   }
  },
  {
   "rule_id": "R-P097-S2-R08-02",
   "status": "OK",
   "label": "통장보유고객우대이율",
   "source": {
    "quote": "2 | 통장보유고객우대이율(연0.3%p) | 직장인우대종합통장 보유고객이 인터넷뱅킹(KB스타뱅킹 포함)으로 가입시 연0.3%p적용"
   },
   "condition": {
    "and": [
     {
      "in": [
       {
        "var": "customer.held_products"
       },
       [
        "직장인우대종합통장"
       ]
      ]
     },
     {
      "in": [
       {
        "var": "contract.channel"
       },
       [
        "INTERNET",
        "MOBILE"
       ]
      ]
     }
