   "source": {
    "quote": "기업여신 우대금리 (연 2.0%p) | 적금 가입일부터 9 개월이 경과한 달의 말일까지주1) 신규 기업대출 보유 시(단, 한도여신 및 수신금리연동부 예금담보대출 제외)"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.start_date",
       "offset_months": 0,
       "day": "first"
      },
      "to": {
       "anchor": "contract.start_date",
       "offset_months": 8,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "exists": {
     "event": "SALARY_TRANSFER",
     "within": {
      "ref": "$window"
     }
    }
   },
