     {
      "count_distinct_months": {
       "event": "DEPOSIT",
       "within": {
        "ref": "$window"
       }
      }
     },
     2
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 2,
    "unit": "%"
   }
  },
